// Source: js/conversationExport/exporters.js
/**
 * Conversation Export - 文本类导出器（Markdown / TXT / JSON）与下载工具
 *
 * 输入统一的导出任务对象 job：
 * {
 *   meta: { title, platformId, platformName, url, exportTime: Date },
 *   options: { showUrl, showTime, showConversationTime, rangeId, formatId },
 *   turns: [{ order, user:{text,images,time}, assistant:{markdown,text,images} }]
 * }
 */

const CETextExporters = {
    roleSelected(turn, role) { return turn.selection?.[role] !== false; },
    /** 只对实际的 Markdown 图片去重，代码示例和转义文本不算图片。 */
    _hasMarkdownImage(markdown, src) {
        if (!markdown || !src) return false;
        return this._markdownImages(markdown).some(image => image.src === src);
    },

    _replaceMarkdownTokens(source, tokens, render) {
        let result = '', last = 0;
        for (const token of tokens) {
            result += source.slice(last, token.start) + render(token);
            last = token.end;
        }
        return result + source.slice(last);
    },

    /** 反引号数量必须匹配，避免多反引号代码示例被拆成普通正文。 */
    _inlineCodeSpans(source) {
        const spans = [];
        for (let index = 0; index < source.length; index++) {
            if (source[index] === '\\') { index++; continue; }
            if (source[index] !== '`') continue;
            const start = index;
            while (source[index] === '`') index++;
            const size = index - start;
            let cursor = index;
            while ((cursor = source.indexOf('`', cursor)) !== -1) {
                const closing = cursor;
                while (source[cursor] === '`') cursor++;
                if (cursor - closing !== size) continue;
                spans.push({ start, end: cursor, text: source.slice(index, closing) });
                index = cursor - 1;
                break;
            }
            if (cursor === -1) index--;
        }
        return spans;
    },

    _maskMarkdownCode(markdown) {
        let fence = null;
        const source = markdown.split('\n').map(line => {
            const content = line.replace(/^(?: {0,3}>[ \t]?)+/, '');
            const match = content.match(/^ {0,3}(`{3,}|~{3,})(.*)$/);
            const code = !!fence || !!match || /^(?: {4}|\t)/.test(content);
            if (fence) {
                if (match && match[1][0] === fence[0] && match[1].length >= fence.length
                    && !match[2].trim()) fence = null;
            } else if (match) {
                fence = match[1];
            }
            return code ? ' '.repeat(line.length) : line;
        }).join('\n');
        return this._replaceMarkdownTokens(source, this._inlineCodeSpans(source),
            span => source.slice(span.start, span.end).replace(/[^\n]/g, ' '));
    },

    /** 读取图片引用的范围，使用括号计数保留 URL；与 PDF 使用同一个解析结果。 */
    _markdownImages(markdown) {
        const source = this._maskMarkdownCode(markdown);
        const unescape = text => text.replace(/\\([\\`*{}\[\]()#+\-.!_>~|])/g, '$1');
        const images = [];
        for (let start = 0; start < source.length; start++) {
            if (source[start] === '\\') { start++; continue; }
            if (!source.startsWith('![', start)) continue;
            let cursor = start + 2, brackets = 1;
            for (; cursor < source.length; cursor++) {
                if (source[cursor] === '\\') { cursor++; continue; }
                if (source[cursor] === '[') brackets++;
                if (source[cursor] === ']' && --brackets === 0) break;
            }
            const labelEnd = cursor;
            if (brackets || source[++cursor] !== '(') continue;
            cursor++;
            while (/\s/.test(source[cursor] || '') && cursor < source.length) cursor++;
            let urlStart = cursor, urlEnd;
            if (source[cursor] === '<') {
                urlStart = ++cursor;
                while (cursor < source.length && source[cursor] !== '>') cursor++;
                if (cursor === source.length) continue;
                urlEnd = cursor++;
            } else {
                let depth = 0;
                for (; cursor < source.length; cursor++) {
                    const char = source[cursor];
                    if (char === '\\') { cursor++; continue; }
                    if (char === '(') depth++;
                    else if (char === ')') { if (!depth) break; depth--; }
                    else if (/\s/.test(char)) break;
                }
                if (depth) continue;
                urlEnd = cursor;
            }
            while (/\s/.test(source[cursor] || '') && cursor < source.length) cursor++;
            if (source[cursor] === '"' || source[cursor] === "'") {
                const quote = source[cursor++];
                while (cursor < source.length && source[cursor] !== quote) {
                    if (source[cursor] === '\\') cursor++;
                    cursor++;
                }
                if (source[cursor++] !== quote) continue;
                while (/\s/.test(source[cursor] || '') && cursor < source.length) cursor++;
            }
            if (source[cursor] !== ')' || urlStart === urlEnd) continue;
            images.push({ start, end: cursor + 1, src: unescape(markdown.slice(urlStart, urlEnd)),
                alt: unescape(markdown.slice(start + 2, labelEnd)) });
            start = cursor;
        }
        return images;
    },

    /**
     * 汇总一轮对话的全部图片（用户 + 助手）。
     */
    _turnImages(turn) {
        const userImages = this.roleSelected(turn, 'user') ? (turn.user?.images || []) : [];
        const assistantImages = this.roleSelected(turn, 'assistant') ? (turn.assistant?.images || []) : [];
        return [...userImages, ...assistantImages];
    },

    _imageInfoLabel(image) {
        const role = image.role === 'user' ? CE_TEXT.exportRoleUser : CE_TEXT.exportRoleAssistant;
        const size = (image.width && image.height) ? `${image.width}x${image.height}` : '未知尺寸';
        const alt = image.alt ? ` ${image.alt}` : '';
        return `${role} · ${size}${alt}`;
    },

    /**
     * 一张图片对应的 Markdown 行：有 src 时输出图片语法 + 信息，
     * 未渲染（bridge 有引用但 DOM 无签名 URL）时只给信息 + 无法内嵌提示。
     */
    _imageMarkdownLines(image) {
        if (image.src) {
            return [
                `![${image.alt || ''}](${image.src})`,
                `> ${CE_TEXT.imageListTitle}：${this._imageInfoLabel(image)}`,
            ];
        }
        return [`> ${CE_TEXT.imageListTitle}：${this._imageInfoLabel(image)}（${CE_TEXT.imageNotRendered}）`];
    },

    /**
     * Markdown 导出。
     * @param {Object} job
     * @returns {string}
     */
    buildMarkdown(job) {
        const { meta, options, turns } = job;
        const lines = [];

        lines.push(`# ${meta.title}`);
        const headerLines = [];
        if (options.showUrl && meta.url) headerLines.push(`> ${CE_TEXT.sourceLabel}: ${meta.url}`);
        if (options.showTime) headerLines.push(`> ${CE_TEXT.timeLabel}: ${ceFormatLocalTime(meta.exportTime)}`);
        if (headerLines.length) {
            lines.push('');
            lines.push(...headerLines);
        }
        lines.push('');
        lines.push('---');

        for (const turn of turns) {
            if (this.roleSelected(turn, 'user')) {
                // 用户
                lines.push('');
                lines.push(`**${CE_TEXT.exportRoleUser}：**`);
                const mdAskTime = options.showConversationTime ? ceFormatChatTime(turn.user?.time) : '';
                if (mdAskTime) {
                    lines.push('');
                    lines.push(`> ${CE_TEXT.askTimeLabel}: ${mdAskTime}`);
                }
                lines.push('');
                lines.push(turn.user?.text ? turn.user.text : CE_TEXT.emptyUserPreview);

                (turn.user?.images || []).forEach(image => {
                    lines.push('');
                    lines.push(...this._imageMarkdownLines(image));
                });

            }
            if (this.roleSelected(turn, 'assistant')) {
                // 助手
                lines.push('');
                lines.push(`**${CE_TEXT.exportRoleAssistant}：**`);
                const mdAsstImages = turn.assistant?.images || [];
                if (turn.assistant?.markdown) {
                    lines.push('');
                    lines.push(turn.assistant.markdown);
                } else if (!mdAsstImages.length) {
                    // 无文本且无图片时才显示占位（纯图片回复不应提示“未找到回复内容”）
                    lines.push('');
                    lines.push(CE_TEXT.emptyAssistant);
                }

                mdAsstImages.filter(image => !this._hasMarkdownImage(turn.assistant?.markdown, image.src)).forEach(image => {
                    lines.push('');
                    lines.push(...this._imageMarkdownLines(image));
                });

            }
            lines.push('');
            lines.push('---');
        }

        return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim() + '\n';
    },

    /**
     * TXT 导出。
     * @param {Object} job
     * @returns {string}
     */
    buildTxt(job) {
        const { meta, options, turns } = job;
        const lines = [];

        lines.push(meta.title);
        if (options.showUrl && meta.url) lines.push(`${CE_TEXT.sourceLabel}: ${meta.url}`);
        if (options.showTime) lines.push(`${CE_TEXT.timeLabel}: ${ceFormatLocalTime(meta.exportTime)}`);
        lines.push('='.repeat(40));

        for (const turn of turns) {
            lines.push('');
            if (this.roleSelected(turn, 'user')) {
                const txtAskTime = options.showConversationTime ? ceFormatChatTime(turn.user?.time) : '';
                lines.push(txtAskTime ? `${CE_TEXT.exportRoleUser}（${txtAskTime}）：` : `${CE_TEXT.exportRoleUser}：`);
                lines.push(turn.user?.text ? turn.user.text : CE_TEXT.emptyUserPreview);
                lines.push('');
            }
            if (this.roleSelected(turn, 'assistant')) {
                lines.push(`${CE_TEXT.exportRoleAssistant}：`);
                if (turn.assistant?.text) {
                    lines.push(turn.assistant.text);
                } else if (!(turn.assistant?.images || []).length) {
                    // 无文本且无图片时才显示占位（图片在下方图片清单中列出）
                    lines.push(CE_TEXT.emptyAssistant);
                }

            }

            const images = this._turnImages(turn);
            if (images.length) {
                lines.push('');
                lines.push(`${CE_TEXT.imageListTitle}：`);
                images.forEach((image, index) => {
                    const tail = image.src ? image.src : `（${CE_TEXT.imageNotRendered}）`;
                    lines.push(`  ${index + 1}. [${this._imageInfoLabel(image)}] ${tail}`);
                });
            }

            lines.push('');
            lines.push('-'.repeat(40));
        }

        return lines.join('\n').replace(/\n{3,}/g, '\n\n').trim() + '\n';
    },

    /**
     * JSON 导出。
     * @param {Object} job
     * @returns {string}
     */
    buildJson(job) {
        const { meta, options, turns } = job;

        const imageCount = turns.reduce((sum, turn) => sum + this._turnImages(turn).length, 0);

        const metadata = {
            title: meta.title,
            platform: meta.platformName || meta.platformId,
            range: options.rangeId,
            format: options.formatId,
            turnCount: turns.length,
            imageCount,
        };
        if (options.showUrl && meta.url) metadata.source = meta.url;
        if (options.showTime) metadata.exportTime = ceFormatLocalTime(meta.exportTime);

        const conversation = turns.map(turn => ({
            order: turn.order,
            ...(this.roleSelected(turn, 'user') ? { user: {
                text: turn.user?.text || '',
                ...(options.showConversationTime && turn.user?.time
                    ? { time: ceFormatChatTime(turn.user.time) }
                    : {}),
                images: (turn.user?.images || []).map(this._serializeImage),
            } } : {}),
            ...(this.roleSelected(turn, 'assistant') ? { assistant: {
                text: turn.assistant?.text || '',
                markdown: turn.assistant?.markdown || '',
                images: (turn.assistant?.images || []).map(this._serializeImage),
            } } : {}),
        }));

        return JSON.stringify({ metadata, conversation }, null, 2);
    },

    /**
     * CSV 导出：每轮一行，列为 序号 /（提问时间）/ Q / A / 图片。
     * 使用 RFC4180 转义（含逗号/引号/换行的字段用双引号包裹、内部引号翻倍），
     * 并加 UTF-8 BOM 便于 Excel 正确识别中文。
     * @param {Object} job
     * @returns {string}
     */
    buildCsv(job) {
        const { meta, options, turns } = job;
        const withTime = !!options.showConversationTime;

        const rows = [];

        // 头部信息（标题总是输出；来源/导出时间跟随开关），以 key,value 预置行放在表格上方
        rows.push(`${this._csvEscape(CE_TEXT.titleLabel)},${this._csvEscape(meta.title)}`);
        if (options.showUrl && meta.url) {
            rows.push(`${this._csvEscape(CE_TEXT.sourceLabel)},${this._csvEscape(meta.url)}`);
        }
        if (options.showTime) {
            rows.push(`${this._csvEscape(CE_TEXT.timeLabel)},${this._csvEscape(ceFormatLocalTime(meta.exportTime))}`);
        }
        rows.push(''); // 空行分隔头部信息与数据表

        const header = ['序号'];
        if (withTime) header.push(CE_TEXT.askTimeLabel);
        header.push(CE_TEXT.exportRoleUser, CE_TEXT.exportRoleAssistant, CE_TEXT.imageListTitle);
        rows.push(header.map(h => this._csvEscape(h)).join(','));

        turns.forEach(turn => {
            const cells = [turn.order];
            if (withTime) cells.push(this.roleSelected(turn, 'user') ? ceFormatChatTime(turn.user?.time) || '' : '');
            cells.push(this.roleSelected(turn, 'user') ? turn.user?.text || '' : '');
            cells.push(this.roleSelected(turn, 'assistant') ? turn.assistant?.text || turn.assistant?.markdown || '' : '');
            const imgs = this._turnImages(turn)
                .map(img => (img.src ? img.src : `（${CE_TEXT.imageNotRendered}）`))
                .join('\n');
            cells.push(imgs);
            rows.push(cells.map(c => this._csvEscape(c)).join(','));
        });

        return '\uFEFF' + rows.join('\r\n') + '\r\n';
    },

    _csvEscape(value) {
        const s = value == null ? '' : String(value);
        return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    },

    _serializeImage(image) {
        return {
            role: image.role,
            src: image.src || '',
            alt: image.alt || '',
            width: image.width || null,
            height: image.height || null,
            fileId: image.fileId || null,
            unrendered: !!image.unrendered,
        };
    },
};

/**
 * 触发浏览器下载。
 * @param {string} filenameBase - 不含扩展名的文件名（已清洗）
 * @param {Object} format - CE_FORMATS 中的格式定义
 * @param {string|Blob} content - 文本内容或 Blob
 */
function ceTriggerDownload(filenameBase, format, content) {
    const blob = content instanceof Blob
        ? content
        : new Blob([content], { type: `${format.mime};charset=utf-8` });

    AITDownload.saveBlob(blob, `${filenameBase}${format.ext}`);
}

;

// Source: js/conversationExport/png-exporter.js
/**
 * Conversation Export - PNG 导出器
 *
 * 无第三方库，纯 Canvas 绘制一张完整长图。
 * - 头部主题色区：标题、来源、导出时间
 * - 正文：逐轮渲染用户/助手内容，尽量呈现接近阅读视图的排版
 *   （段落、标题、列表、引用、代码块、图片）
 * - 图片：尝试内嵌；无法加载/跨域受限时显示占位提示
 * - 超长对话：当高度超过浏览器画布上限时截断，并显示提示
 */

class CEPngExporter {
    constructor() {
        this.PAGE_WIDTH = 820;
        this.PADDING_X = 40;
        this.contentWidth = this.PAGE_WIDTH - this.PADDING_X * 2;
        // 正文区（提问+回复）左右留白更窄，让内容更宽
        this.BODY_PADDING_X = 24;
        // 左侧 Q/A 标记栏：正文内容整体右移，标记画在这条栏里、与首行对齐
        this.MARKER_GUTTER = 38;
        this.contentX = this.BODY_PADDING_X + this.MARKER_GUTTER;
        this.bodyWidth = this.PAGE_WIDTH - this.contentX - this.BODY_PADDING_X;
        this.IMAGE_LOAD_TIMEOUT = 8000;
        this.MAX_IMAGE_HEIGHT = 460;

        this.fontFamily = '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "PingFang SC", "Microsoft YaHei", Helvetica, Arial, sans-serif';
        this.monoFamily = '"SF Mono", "Cascadia Code", Consolas, "Courier New", monospace';

        this.colors = {
            bg: '#ffffff',
            text: '#1f2937',
            subtle: '#6b7280',
            userBg: '#f3f4f6',
            assistantRule: '#e5e7eb',
            codeBg: '#f6f8fa',
            codeText: '#24292e',
            quoteBar: '#d1d5db',
            divider: '#e5e7eb',
            placeholderBg: '#f3f4f6',
            placeholderText: '#9ca3af',
        };
    }

    /**
     * 导出 PNG。
     * @param {Object} job
     * @param {string} themeId
     * @returns {Promise<Blob>}
     */
    async export(job, themeId) {
        const canvas = await this.renderCanvas(job, themeId);
        return await this._canvasToBlob(canvas);
    }

    /**
     * 渲染整张长图到 canvas（供 PNG / PDF 复用，保证两种格式视觉一致）。
     * @param {Object} job
     * @param {string} themeId
     * @returns {Promise<HTMLCanvasElement>}
     */
    async renderCanvas(job, themeId) {
        const theme = ceGetTheme(themeId);
        const dpr = Math.min(window.devicePixelRatio || 1, 2);

        // 测量用 ctx
        const measureCanvas = document.createElement('canvas');
        const measureCtx = measureCanvas.getContext('2d');

        // 预加载图片
        const imageMap = await this._preloadImages(job.turns);

        // 仅在导出内容实际包含公式时加载 MathJax 并预渲染，普通 PNG 导出不加载重型库
        const hasFormulas = job.turns.some((turn) =>
            CETextExporters.roleSelected(turn, 'assistant') && this._collectFormulas(turn.assistant?.markdown || '').length > 0
        );
        this.formulaCapable = hasFormulas
            ? await this._probeFormulaRendering()
            : false;
        this.formulaImages = this.formulaCapable
            ? await this._preloadFormulas(job.turns)
            : new Map();

        // 构建绘制操作（含测量高度）
        const headerBlock = this._buildHeader(measureCtx, job, theme);
        const bodyOps = this._buildBodyOps(measureCtx, job, imageMap, theme);

        // 计算高度并处理截断
        const { ops, totalHeight, truncated } = this._layout(measureCtx, headerBlock.height, bodyOps);

        // 真正绘制
        const canvas = document.createElement('canvas');
        canvas.width = Math.round(this.PAGE_WIDTH * dpr);
        canvas.height = Math.round(totalHeight * dpr);
        const ctx = canvas.getContext('2d');
        ctx.scale(dpr, dpr);
        ctx.textBaseline = 'top';

        // 背景
        ctx.fillStyle = this.colors.bg;
        ctx.fillRect(0, 0, this.PAGE_WIDTH, totalHeight);

        // 头部
        headerBlock.paint(ctx, 0, theme);

        // 正文
        let y = headerBlock.height;
        for (const op of ops) {
            op.paint(ctx, y);
            y += op.height;
        }

        // 截断提示
        if (truncated) {
            this._paintTruncationNotice(ctx, y);
        }

        return canvas;
    }

    // ==================== 布局/截断 ====================

    _layout(ctx, headerHeight, bodyOps) {
        const maxBody = CE_MAX_CANVAS_HEIGHT - headerHeight - 80; // 预留底部边距/提示
        const ops = [];
        let used = 0;
        let truncated = false;

        for (const op of bodyOps) {
            if (used + op.height > maxBody) {
                truncated = true;
                break;
            }
            ops.push(op);
            used += op.height;
        }

        const bottomPadding = 32;
        const noticeSpace = truncated ? 56 : 0;
        const totalHeight = Math.ceil(headerHeight + used + bottomPadding + noticeSpace);
        return { ops, totalHeight, truncated };
    }

    _paintTruncationNotice(ctx, y) {
        this._setFont(ctx, { size: 14, weight: '500' });
        ctx.fillStyle = this.colors.subtle;
        ctx.textAlign = 'center';
        ctx.fillText(CE_TEXT.truncatedNotice, this.PAGE_WIDTH / 2, y + 16);
        ctx.textAlign = 'left';
    }

    // ==================== 头部 ====================

    _buildHeader(ctx, job, theme) {
        const padX = this.PADDING_X;
        const padTop = 32;
        const innerWidth = this.contentWidth;

        this._setFont(ctx, { size: 24, weight: '700' });
        const titleLines = this._wrapText(ctx, job.meta.title || '', innerWidth);

        const metaLines = [];
        if (job.options.showUrl && job.meta.url) {
            metaLines.push(`${CE_TEXT.sourceLabel}: ${job.meta.url}`);
        }
        if (job.options.showTime) {
            metaLines.push(`${CE_TEXT.timeLabel}: ${ceFormatLocalTime(job.meta.exportTime)}`);
        }

        const titleLineHeight = 32;
        const metaLineHeight = 20;
        const gap = metaLines.length ? 14 : 0;
        const height = padTop + titleLines.length * titleLineHeight + gap +
            metaLines.length * metaLineHeight + 28;

        const self = this;
        return {
            height,
            paint(c, top, themeDef) {
                // 主题背景
                self._fillThemeBackground(c, top, height, themeDef);

                c.fillStyle = themeDef.textColor;
                c.textAlign = 'left';

                let cursor = top + padTop;
                self._setFont(c, { size: 24, weight: '700' });
                for (const line of titleLines) {
                    c.fillText(line, padX, cursor);
                    cursor += titleLineHeight;
                }

                if (metaLines.length) {
                    cursor += gap - 6;
                    self._setFont(c, { size: 13, weight: '400' });
                    c.globalAlpha = 0.9;
                    for (const line of metaLines) {
                        const clipped = self._clipToWidth(c, line, innerWidth);
                        c.fillText(clipped, padX, cursor);
                        cursor += metaLineHeight;
                    }
                    c.globalAlpha = 1;
                }
            },
        };
    }

    _fillThemeBackground(ctx, top, height, theme) {
        if (theme.gradient) {
            // 135deg 渐变
            const grad = ctx.createLinearGradient(0, top, this.PAGE_WIDTH, top + height);
            theme.gradient.forEach(([offset, color]) => grad.addColorStop(offset, color));
            ctx.fillStyle = grad;
        } else {
            ctx.fillStyle = theme.solid || '#0d0d0d';
        }
        ctx.fillRect(0, top, this.PAGE_WIDTH, height);
    }

    // ==================== 正文 ====================

    _buildBodyOps(ctx, job, imageMap, theme) {
        const ops = [];

        // 正文与顶部主题区之间留出间距，避免首个内容贴着头部
        ops.push(this._spacerOp(18));

        job.turns.forEach((turn, index) => {
            if (index > 0) ops.push(this._dividerOp());

            if (CETextExporters.roleSelected(turn, 'user')) {
                // 提问：首个内容块（气泡）挂上左侧「Q」标记，与首行对齐
                const askTime = job.options?.showConversationTime ? ceFormatChatTime(turn.user?.time) : '';
                const userOp = this._userTextOp(ctx, turn.user?.text || CE_TEXT.emptyUserPreview, askTime);
                ops.push(this._withRoleMarker(userOp, 'Q', true, theme));
                (turn.user?.images || []).forEach(image => {
                    ops.push(this._imageOp(image, imageMap));
                });

                // 提问与回答之间留一点间距
                if (CETextExporters.roleSelected(turn, 'assistant')) ops.push(this._spacerOp(10));

            }
            if (CETextExporters.roleSelected(turn, 'assistant')) {
                // 回答：文本块 + 图片；图片也算内容，避免纯图片回复被判为“空”
                const assistantOps = [];
                const blocks = this._parseMarkdownBlocks(turn.assistant?.markdown || '');
                if (blocks.length) {
                    blocks.forEach(block => assistantOps.push(this._markdownBlockOp(ctx, block)));
                } else if (turn.assistant?.text) {
                    assistantOps.push(this._paragraphOp(ctx, turn.assistant.text));
                }
                (turn.assistant?.images || []).forEach(image => {
                    assistantOps.push(this._imageOp(image, imageMap));
                });
                // 文本与图片都没有时才显示占位提示
                if (!assistantOps.length) {
                    assistantOps.push(this._paragraphOp(ctx, CE_TEXT.emptyAssistant));
                }
                // 首个回答内容（文本或图片）挂上左侧「A」标记
                assistantOps[0] = this._withRoleMarker(assistantOps[0], 'A', false, theme);
                assistantOps.forEach(op => ops.push(op));
            }
        });

        return ops;
    }

    _spacerOp(height) {
        return { height, paint() { /* 纯占位间距 */ } };
    }

    /**
     * 给一个内容块 op 附加左侧栏的「Q / A」圆形标记，垂直对齐到该块的首行中心。
     * @param {Object} op - 原始 op（需可选携带 markerCenter：首行中心相对 op 顶部的偏移）
     * @param {string} letter - 'Q' | 'A'
     * @param {boolean} isQuestion - 提问用主题色，回答用中性灰
     * @param {Object} theme - 头部主题（用于取 Q 标记的强调色）
     */
    _withRoleMarker(op, letter, isQuestion, theme) {
        const self = this;
        const center = (op.markerCenter != null) ? op.markerCenter : 16;
        const origPaint = op.paint;
        return {
            height: op.height,
            markerCenter: op.markerCenter,
            paint(c, y) {
                origPaint.call(op, c, y);
                self._paintRoleMarker(c, y + center, letter, isQuestion, theme);
            },
        };
    }

    _paintRoleMarker(c, centerY, letter, isQuestion, theme) {
        const r = 14;
        const cx = this.BODY_PADDING_X + r;

        let bg = '#e5e7eb';
        let fg = '#4b5563';
        if (isQuestion) {
            bg = (theme && theme.gradient) ? theme.gradient[0][1] : (theme && theme.solid) || '#6128ff';
            fg = '#ffffff';
        }

        c.beginPath();
        c.arc(cx, centerY, r, 0, Math.PI * 2);
        c.fillStyle = bg;
        c.fill();

        this._setFont(c, { size: 14, weight: '700' });
        c.fillStyle = fg;
        c.textAlign = 'center';
        c.textBaseline = 'middle';
        c.fillText(letter, cx, centerY + 0.5);
        c.textAlign = 'left';
        c.textBaseline = 'top';
    }

    _dividerOp() {
        const self = this;
        return {
            height: 33,
            paint(c, y) {
                c.strokeStyle = self.colors.divider;
                c.lineWidth = 1;
                c.beginPath();
                c.moveTo(self.BODY_PADDING_X, y + 16);
                c.lineTo(self.PAGE_WIDTH - self.BODY_PADDING_X, y + 16);
                c.stroke();
            },
        };
    }

    _userTextOp(ctx, text, timeText = '') {
        const self = this;
        const padding = 14;
        const lineHeight = 22;
        const timeHeight = timeText ? 20 : 0;
        this._setFont(ctx, { size: 15, weight: '400' });
        const lines = this._wrapText(ctx, text, this.bodyWidth - padding * 2);
        const boxHeight = lines.length * lineHeight + padding * 2 + timeHeight;

        return {
            height: boxHeight + 10,
            // 顶部第一行中心（有时间则为时间行，否则为正文首行），用于左侧 Q 标记对齐
            markerCenter: padding + (timeHeight || lineHeight) / 2,
            paint(c, y) {
                const boxTop = y;
                self._roundRect(c, self.contentX, boxTop, self.bodyWidth, boxHeight, 10);
                c.fillStyle = self.colors.userBg;
                c.fill();

                c.textAlign = 'left';
                let textTop = boxTop + padding;

                // 提问时间：小号浅色，置于气泡顶部
                if (timeText) {
                    self._setFont(c, { size: 12, weight: '400' });
                    c.fillStyle = self.colors.subtle;
                    c.textBaseline = 'top';
                    c.fillText(timeText, self.contentX + padding, textTop);
                    textTop += timeHeight;
                }

                self._setFont(c, { size: 15, weight: '400' });
                c.fillStyle = self.colors.text;
                c.textBaseline = 'middle';
                let cursor = textTop + lineHeight / 2;
                for (const line of lines) {
                    c.fillText(line, self.contentX + padding, cursor);
                    cursor += lineHeight;
                }
                c.textBaseline = 'top';
            },
        };
    }

    _paragraphOp(ctx, text) {
        return this._richTextOp(ctx, text, {
            font: { size: 15, weight: '400' },
            lineHeight: 23,
            topPad: 4,
            bottomPad: 6,
        });
    }

    /**
     * 通用富文本块渲染：支持内联公式（文本 + 公式图片混排），
     * 可选列表标记 / 引用竖条 / 缩进。段落、列表项、标题、引用共用。
     * @param {CanvasRenderingContext2D} ctx
     * @param {string} rawText - 原始文本（含内联 $...$，此处才做公式切分与清洗）
     * @param {Object} opts
     */
    _richTextOp(ctx, rawText, opts) {
        const self = this;
        const font = opts.font;
        const lineHeight = opts.lineHeight || 23;
        const color = opts.color || this.colors.text;
        const indent = opts.indent || 0;
        const marker = opts.marker || null;
        const markerDx = opts.markerDx || 0;
        const topPad = opts.topPad != null ? opts.topPad : 4;
        const bottomPad = opts.bottomPad != null ? opts.bottomPad : 6;
        const quoteBar = !!opts.quoteBar;

        const maxWidth = opts.maxWidth ?? (this.bodyWidth - indent);
        const tokens = this._tokenizeInline(rawText);
        const hasFormula = tokens.some(t => t.type === 'formula');

        let lines;
        if (hasFormula) {
            lines = this._layoutInline(ctx, tokens, maxWidth, font);
        } else {
            const plain = tokens.map(t => t.text).join('');
            this._setFont(ctx, font);
            lines = this._wrapText(ctx, plain, maxWidth).map(t => [{ type: 'text', text: t, w: 0 }]);
        }

        const innerHeight = lines.length * lineHeight;
        return {
            height: innerHeight + topPad + bottomPad,
            // 首行中心，用于左侧 A 标记对齐
            markerCenter: topPad + lineHeight / 2,
            paint(c, y) {
                c.textAlign = 'left';
                if (quoteBar) {
                    c.fillStyle = self.colors.quoteBar;
                    c.fillRect(self.contentX, y + topPad, 3, innerHeight);
                }
                if (marker) {
                    self._setFont(c, font);
                    c.fillStyle = color;
                    c.fillText(marker, self.contentX + markerDx, y + topPad);
                }
                let cursor = y + topPad;
                const startX = self.contentX + indent;
                for (const line of lines) {
                    let cx = startX;
                    for (const item of line) {
                        if (item.type === 'formula' && item.entry && item.entry.element) {
                            try {
                                c.drawImage(item.entry.element, cx, cursor + (lineHeight - item.h) / 2 - 2, item.w, item.h);
                            } catch {
                                self._setFont(c, font);
                                c.fillStyle = color;
                                c.fillText(item.fallback, cx, cursor);
                            }
                        } else if (item.type === 'formula') {
                            self._setFont(c, font);
                            c.fillStyle = color;
                            c.fillText(item.fallback, cx, cursor);
                        } else {
                            self._setFont(c, font);
                            c.fillStyle = color;
                            c.fillText(item.text, cx, cursor);
                        }
                        cx += (item.w || 0);
                    }
                    cursor += lineHeight;
                }
            },
        };
    }

    /**
     * 将含内联公式的文本切分为 token：文本片段与 {latex} 公式片段。
     * 文本片段会做内联标记清洗，公式片段保留原始 LaTeX。
     */
    _tokenizeInline(rawText) {
        const tokens = [];
        const re = /\$([^$\n]+?)\$/g;
        let last = 0;
        let m;
        while ((m = re.exec(rawText)) !== null) {
            if (m.index > last) {
                tokens.push({ type: 'text', text: this._cleanInline(rawText.slice(last, m.index)) });
            }
            tokens.push({ type: 'formula', latex: m[1].trim() });
            last = re.lastIndex;
        }
        if (last < rawText.length) {
            tokens.push({ type: 'text', text: this._cleanInline(rawText.slice(last)) });
        }
        return tokens;
    }

    /**
     * 行内混排布局：文本按字符换行，公式作为整体盒子换行。
     * @returns {Array<Array<{type,text?,entry?,w,h?,fallback?}>>}
     */
    _layoutInline(ctx, tokens, maxWidth, font) {
        const inlineH = Math.round((font && font.size ? font.size : 15) * 1.15);
        const lines = [];
        let line = [];
        let x = 0;
        const pushLine = () => { lines.push(line); line = []; x = 0; };

        for (const token of tokens) {
            if (token.type === 'text') {
                this._setFont(ctx, font);
                for (const ch of token.text) {
                    const cw = ctx.measureText(ch).width;
                    if (x + cw > maxWidth && line.length) pushLine();
                    const lastItem = line[line.length - 1];
                    if (lastItem && lastItem.type === 'text') {
                        lastItem.text += ch;
                        lastItem.w += cw;
                    } else {
                        line.push({ type: 'text', text: ch, w: cw });
                    }
                    x += cw;
                }
            } else {
                const key = 'I:' + token.latex;
                const entry = (this.formulaCapable && this.formulaImages) ? this.formulaImages.get(key) : null;
                const usable = !!(entry && entry.element);
                let w;
                let h = inlineH;
                if (usable) {
                    w = entry.width * (inlineH / entry.height);
                } else {
                    this._setFont(ctx, font);
                    w = ctx.measureText(token.latex).width;
                }
                if (x + w > maxWidth && line.length) pushLine();
                line.push({ type: 'formula', entry: usable ? entry : null, w, h, fallback: token.latex });
                x += w;
            }
        }
        if (line.length) pushLine();
        return lines;
    }

    _markdownBlockOp(ctx, block) {
        switch (block.kind) {
            case 'heading': return this._headingOp(ctx, block);
            case 'listitem': return this._listItemOp(ctx, block);
            case 'quote': return this._quoteOp(ctx, block);
            case 'code': return this._codeOp(ctx, block);
            case 'formula': return this._formulaBlockOp(ctx, block);
            case 'table': return this._tableOp(ctx, block);
            default: return this._paragraphOp(ctx, block.text);
        }
    }

    _tableOp(ctx, block) {
        const columnCount = block.headers.length;
        const columnWidth = this.bodyWidth / columnCount;
        const rows = [block.headers, ...block.rows].map((row, rowIndex) => {
            const cells = Array.from({ length: columnCount }, (_, column) => this._richTextOp(
                ctx, row[column] || '', {
                    font: { size: 14, weight: rowIndex === 0 ? '600' : '400' },
                    lineHeight: 22,
                    indent: column * columnWidth + 8,
                    maxWidth: Math.max(1, columnWidth - 16),
                    topPad: 8,
                    bottomPad: 8,
                }
            ));
            return { cells, height: Math.max(38, ...cells.map(cell => cell.height)) };
        });
        const self = this;
        return {
            height: rows.reduce((sum, row) => sum + row.height, 0) + 12,
            markerCenter: 23,
            paint(c, y) {
                let top = y + 4;
                rows.forEach((row, index) => {
                    if (index === 0) {
                        c.fillStyle = self.colors.codeBg;
                        c.fillRect(self.contentX, top, self.bodyWidth, row.height);
                    }
                    row.cells.forEach((cell, column) => {
                        const left = self.contentX + column * columnWidth;
                        c.strokeStyle = self.colors.assistantRule;
                        c.lineWidth = 1;
                        c.strokeRect(left, top, columnWidth, row.height);
                        c.save();
                        c.beginPath();
                        c.rect(left + 1, top + 1, columnWidth - 2, row.height - 2);
                        c.clip();
                        cell.paint(c, top);
                        c.restore();
                    });
                    top += row.height;
                });
            },
        };
    }

    _formulaBlockOp(ctx, block) {
        const self = this;
        const key = 'D:' + block.latex;
        const entry = (this.formulaCapable && this.formulaImages) ? this.formulaImages.get(key) : null;

        if (entry && entry.element) {
            let w = entry.width;
            let h = entry.height;
            if (w > this.bodyWidth) {
                const ratio = this.bodyWidth / w;
                w = this.bodyWidth;
                h = h * ratio;
            }
            return {
                height: h + 24,
                markerCenter: 12 + h / 2,
                paint(c, y) {
                    const x = self.contentX + (self.bodyWidth - w) / 2;
                    try {
                        c.drawImage(entry.element, x, y + 12, w, h);
                    } catch {
                        self._paintCenteredText(c, y, block.latex);
                    }
                },
            };
        }

        // 回退：居中显示 LaTeX 文本
        const lineHeight = 23;
        this._setFont(ctx, { size: 15, weight: '400' });
        const lines = this._wrapText(ctx, block.latex, this.bodyWidth);
        return {
            height: lines.length * lineHeight + 16,
            markerCenter: 8 + lineHeight / 2,
            paint(c, y) {
                self._setFont(c, { size: 15, weight: '400' });
                c.fillStyle = self.colors.text;
                c.textAlign = 'center';
                let cursor = y + 8;
                for (const line of lines) {
                    c.fillText(line, self.contentX + self.bodyWidth / 2, cursor);
                    cursor += lineHeight;
                }
                c.textAlign = 'left';
            },
        };
    }

    _paintCenteredText(ctx, y, text) {
        this._setFont(ctx, { size: 15, weight: '400' });
        ctx.fillStyle = this.colors.text;
        ctx.textAlign = 'center';
        ctx.fillText(text, this.contentX + this.bodyWidth / 2, y + 12);
        ctx.textAlign = 'left';
    }

    _headingOp(ctx, block) {
        const size = block.level <= 1 ? 20 : block.level === 2 ? 18 : 16;
        return this._richTextOp(ctx, block.text, {
            font: { size, weight: '700' },
            lineHeight: size + 8,
            topPad: 8,
            bottomPad: 4,
        });
    }

    _listItemOp(ctx, block) {
        const marker = block.ordered ? `${block.index}.` : '•';
        return this._richTextOp(ctx, block.text, {
            font: { size: 15, weight: '400' },
            lineHeight: 23,
            indent: 22 + block.depth * 18,
            marker,
            markerDx: block.depth * 18,
            topPad: 3,
            bottomPad: 3,
        });
    }

    _quoteOp(ctx, block) {
        const paragraphs = block.text.split(/\n\s*\n/).filter(text => text.trim());
        const ops = paragraphs.map(text => this._richTextOp(ctx, text, {
            font: { size: 15, weight: '400' },
            lineHeight: 23,
            indent: 18,
            color: this.colors.subtle,
            quoteBar: true,
            topPad: 2,
            bottomPad: 10,
        }));
        return {
            height: ops.reduce((sum, op) => sum + op.height, 0),
            markerCenter: ops[0]?.markerCenter,
            paint(c, y) {
                for (const op of ops) {
                    op.paint(c, y);
                    y += op.height;
                }
            },
        };
    }

    _codeOp(ctx, block) {
        const self = this;
        const padding = 14;
        const lineHeight = 20;
        this._setFont(ctx, { size: 13, mono: true });
        const rawLines = block.code.split('\n');
        const wrapped = [];
        rawLines.forEach(line => {
            const parts = this._wrapText(ctx, line || ' ', this.bodyWidth - padding * 2);
            wrapped.push(...(parts.length ? parts : ['']));
        });
        const boxHeight = wrapped.length * lineHeight + padding * 2;

        return {
            height: boxHeight + 12,
            markerCenter: padding + lineHeight / 2,
            paint(c, y) {
                self._roundRect(c, self.contentX, y, self.bodyWidth, boxHeight, 8);
                c.fillStyle = self.colors.codeBg;
                c.fill();

                self._setFont(c, { size: 13, mono: true });
                c.fillStyle = self.colors.codeText;
                c.textAlign = 'left';
                let cursor = y + padding;
                for (const line of wrapped) {
                    c.fillText(line, self.contentX + padding, cursor);
                    cursor += lineHeight;
                }
            },
        };
    }

    _imageOp(image, imageMap) {
        const self = this;
        const entry = imageMap.get(image.src);

        if (entry && entry.element) {
            const naturalW = entry.width || entry.element.naturalWidth || 1;
            const naturalH = entry.height || entry.element.naturalHeight || 1;
            const drawWidth = Math.min(naturalW, this.bodyWidth);
            let drawHeight = (naturalH / naturalW) * drawWidth;
            let finalWidth = drawWidth;
            if (drawHeight > this.MAX_IMAGE_HEIGHT) {
                const ratio = this.MAX_IMAGE_HEIGHT / drawHeight;
                drawHeight = this.MAX_IMAGE_HEIGHT;
                finalWidth = drawWidth * ratio;
            }
            return {
                height: drawHeight + 16,
                markerCenter: 8 + 14,
                paint(c, y) {
                    try {
                        c.drawImage(entry.element, self.contentX, y + 8, finalWidth, drawHeight);
                    } catch {
                        self._paintImagePlaceholder(c, y);
                    }
                },
            };
        }

        return {
            height: 56,
            markerCenter: 8 + 14,
            paint(c, y) {
                self._paintImagePlaceholder(c, y);
            },
        };
    }

    _paintImagePlaceholder(ctx, y) {
        const height = 40;
        this._roundRect(ctx, this.contentX, y + 8, this.bodyWidth, height, 8);
        ctx.fillStyle = this.colors.placeholderBg;
        ctx.fill();
        this._setFont(ctx, { size: 13, weight: '400' });
        ctx.fillStyle = this.colors.placeholderText;
        ctx.textAlign = 'center';
        ctx.fillText(CE_TEXT.imageCannotEmbed, this.contentX + this.bodyWidth / 2, y + 8 + height / 2 - 7);
        ctx.textAlign = 'left';
    }

    // ==================== Markdown 轻量解析 ====================

    _splitTableRow(line) {
        const cells = [];
        let cell = '';
        const source = line.trim();
        for (let index = 0; index < source.length; index++) {
            if (source[index] === '\\' && source[index + 1] === '|') {
                cell += '|';
                index++;
            } else if (source[index] === '|') {
                cells.push(cell.trim());
                cell = '';
            } else {
                cell += source[index];
            }
        }
        cells.push(cell.trim());
        if (source.startsWith('|')) cells.shift();
        if (source.endsWith('|')) cells.pop();
        return cells;
    }

    _parseMarkdownBlocks(markdown) {
        const blocks = [];
        if (!markdown) return blocks;

        const lines = markdown.split('\n');
        let i = 0;
        let paragraph = [];

        const flushParagraph = () => {
            if (paragraph.length) {
                // 保留原始文本（含内联 $...$），清洗与公式切分留到渲染时处理
                const raw = paragraph.join(' ').trim();
                if (raw) blocks.push({ kind: 'paragraph', text: raw });
                paragraph = [];
            }
        };

        while (i < lines.length) {
            const line = lines[i];
            const trimmed = line.trim();

            // 代码块
            const fence = trimmed.match(/^```(.*)$/);
            if (fence) {
                flushParagraph();
                const lang = fence[1].trim();
                const codeLines = [];
                i++;
                while (i < lines.length && !lines[i].trim().startsWith('```')) {
                    codeLines.push(lines[i]);
                    i++;
                }
                i++; // 跳过结束 fence
                blocks.push({ kind: 'code', lang, code: codeLines.join('\n') });
                continue;
            }

            // 独立公式块：$$ 独占一行作为起止围栏（与 dom-to-markdown 输出一致）
            if (trimmed === '$$') {
                flushParagraph();
                const formulaLines = [];
                i++;
                while (i < lines.length && lines[i].trim() !== '$$') {
                    formulaLines.push(lines[i]);
                    i++;
                }
                i++; // 跳过结束 $$
                blocks.push({ kind: 'formula', latex: formulaLines.join('\n').trim() });
                continue;
            }

            if (trimmed === '') {
                flushParagraph();
                i++;
                continue;
            }

            // 标题
            const heading = trimmed.match(/^(#{1,6})\s+(.*)$/);
            if (heading) {
                flushParagraph();
                blocks.push({
                    kind: 'heading',
                    level: heading[1].length,
                    text: heading[2].trim(),
                });
                i++;
                continue;
            }

            // 分隔线
            if (/^(-{3,}|\*{3,}|_{3,})$/.test(trimmed)) {
                flushParagraph();
                i++;
                continue;
            }

            // 引用
            const quote = line.match(/^\s*>\s?(.*)$/);
            if (quote) {
                flushParagraph();
                const quoteText = [quote[1]];
                i++;
                while (i < lines.length && /^\s*>\s?/.test(lines[i])) {
                    quoteText.push(lines[i].replace(/^\s*>\s?/, ''));
                    i++;
                }
                blocks.push({ kind: 'quote', text: quoteText.join('\n').trim() });
                continue;
            }

            // 列表项
            const listMatch = line.match(/^(\s*)([-*+]|\d+\.)\s+(.*)$/);
            if (listMatch) {
                flushParagraph();
                const depth = Math.min(Math.floor(listMatch[1].length / 2), 4);
                const ordered = /\d+\./.test(listMatch[2]);
                const index = ordered ? parseInt(listMatch[2], 10) : 0;
                blocks.push({
                    kind: 'listitem',
                    depth,
                    ordered,
                    index,
                    text: listMatch[3].trim(),
                });
                i++;
                continue;
            }

            // Markdown 表格：保留行列，分隔线不会作为普通正文输出。
            if (trimmed.includes('|') && i + 1 < lines.length) {
                const headers = this._splitTableRow(trimmed);
                const separator = this._splitTableRow(lines[i + 1]);
                if (headers.length && separator.length === headers.length
                    && separator.every(cell => /^:?-{3,}:?$/.test(cell))) {
                    flushParagraph();
                    const rows = [];
                    i += 2;
                    while (i < lines.length && lines[i].trim() && lines[i].includes('|')) {
                        rows.push(this._splitTableRow(lines[i]));
                        i++;
                    }
                    blocks.push({ kind: 'table', headers, rows });
                    continue;
                }
            }

            // 普通段落（累积连续行）
            paragraph.push(trimmed);
            i++;
        }

        flushParagraph();
        return blocks;
    }

    /**
     * 去除 markdown 内联标记，转为适合 PNG 渲染的纯文本。
     */
    _cleanInline(text) {
        return (text || '')
            .replace(/!\[[^\]]*\]\([^)]*\)/g, '')          // 图片
            .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')        // 链接 → 文本
            .replace(/`([^`]+)`/g, '$1')                    // 行内代码
            .replace(/\*\*([^*]+)\*\*/g, '$1')              // 粗体
            .replace(/__([^_]+)__/g, '$1')
            .replace(/\*([^*]+)\*/g, '$1')                  // 斜体
            .replace(/(^|[^\w])_([^_]+)_($|[^\w])/g, '$1$2$3')
            .replace(/\s+/g, ' ')
            .trim();
    }

    // ==================== 图片预加载 ====================

    async _preloadImages(turns) {
        const srcs = new Set();
        turns.forEach(turn => {
            CETextExporters._turnImages(turn).forEach(img => srcs.add(img.src));
        });

        const map = new Map();
        await Promise.all(Array.from(srcs).map(async (src) => {
            const result = await this._loadImage(src);
            map.set(src, result);
        }));
        return map;
    }

    _loadImage(src) {
        return new Promise((resolve) => {
            const img = new Image();
            let settled = false;
            const finish = (value) => {
                if (settled) return;
                settled = true;
                resolve(value);
            };

            const timer = setTimeout(() => finish({ element: null }), this.IMAGE_LOAD_TIMEOUT);

            img.crossOrigin = 'anonymous';
            img.onload = () => {
                clearTimeout(timer);
                finish({ element: img, width: img.naturalWidth, height: img.naturalHeight });
            };
            img.onerror = () => {
                clearTimeout(timer);
                finish({ element: null });
            };

            try {
                img.src = src;
            } catch {
                clearTimeout(timer);
                finish({ element: null });
            }
        });
    }

    // ==================== 公式渲染（LaTeX → MathML → SVG 图片）====================

    /**
     * 探测公式图片渲染是否可用且不会污染 canvas。
     * 用一个最小公式预先验证（渲染 + 绘制 + toDataURL 读回），
     * 若 MathJax 不可用或画布被污染则整体回退到 LaTeX 文本，保证导出不失败。
     * @returns {Promise<boolean>}
     */
    async _probeFormulaRendering() {
        try {
            const entry = await this._renderLatexToImage('x^2', false);
            if (!entry || !entry.element) return false;
            const test = document.createElement('canvas');
            test.width = 4;
            test.height = 4;
            const tctx = test.getContext('2d');
            tctx.drawImage(entry.element, 0, 0, 4, 4);
            test.toDataURL(); // 若画布被污染会抛出 SecurityError
            return true;
        } catch {
            return false;
        }
    }

    /**
     * 预渲染选中对话中出现的全部公式（去重）。
     * @returns {Promise<Map<string, {element:Image,width:number,height:number}|null>>}
     */
    async _preloadFormulas(turns) {
        const map = new Map();
        if (!this.formulaCapable) return map;

        const seen = new Set();
        const items = [];
        turns.forEach(turn => {
            if (!CETextExporters.roleSelected(turn, 'assistant')) return;
            this._collectFormulas(turn.assistant?.markdown || '').forEach(f => {
                const key = (f.display ? 'D:' : 'I:') + f.latex;
                if (!seen.has(key)) {
                    seen.add(key);
                    items.push({ key, latex: f.latex, display: f.display });
                }
            });
        });

        await Promise.all(items.map(async (item) => {
            const entry = await this._renderLatexToImage(item.latex, item.display);
            map.set(item.key, entry);
        }));
        return map;
    }

    /**
     * 从一段 markdown 中收集公式（$$ 独立公式与 $...$ 内联公式）。
     */
    _collectFormulas(markdown) {
        const result = [];
        if (!markdown) return result;

        let m;
        const displayRe = /\$\$([\s\S]+?)\$\$/g;
        while ((m = displayRe.exec(markdown)) !== null) {
            const latex = m[1].trim();
            if (latex) result.push({ latex, display: true });
        }

        const inlineSource = markdown.replace(/\$\$[\s\S]+?\$\$/g, ' ');
        const inlineRe = /\$([^$\n]+?)\$/g;
        while ((m = inlineRe.exec(inlineSource)) !== null) {
            const latex = m[1].trim();
            if (latex) result.push({ latex, display: false });
        }
        return result;
    }

    /**
     * 确保 MathJax 就绪（tex2svg 可用）。
     * @returns {Promise<boolean>}
     */
    async _ensureMathJax() {
        if (this._mathjaxReady) return this._mathjaxReady;
        this._mathjaxReady = (async () => {
            try {
                await window.AITResourceLoader?.load('export-mathjax');
                if (typeof MathJax === 'undefined') return false;
                if (MathJax.startup && MathJax.startup.promise) {
                    await MathJax.startup.promise;
                }
                return typeof MathJax.tex2svg === 'function';
            } catch {
                return false;
            }
        })();
        const ready = await this._mathjaxReady;
        if (!ready) {
            this._mathjaxReady = null;
        }
        return ready;
    }

    /**
     * 将 LaTeX 渲染为图片：用 MathJax 输出自包含的 SVG（字形为矢量路径），
     * 再作为图片加载。SVG 不含 foreignObject/外部字体，可安全绘制到 canvas。
     * @param {string} latex
     * @param {boolean} displayMode
     * @returns {Promise<{element:Image,width:number,height:number}|null>}
     */
    async _renderLatexToImage(latex, displayMode) {
        if (!latex) return null;

        const ready = await this._ensureMathJax();
        if (!ready) return null;

        const fontSize = displayMode ? 22 : 17;
        const color = this.colors.text;

        let svg;
        try {
            const node = MathJax.tex2svg(latex, { display: displayMode });
            svg = node.querySelector('svg');
        } catch {
            return null;
        }
        if (!svg) return null;

        // 在真实 DOM 中按目标字号测量像素尺寸（MathJax SVG 默认使用 ex 单位）
        const probe = document.createElement('div');
        probe.style.cssText = `position:absolute;left:-99999px;top:0;visibility:hidden;font-size:${fontSize}px;`;
        probe.appendChild(svg);
        document.body.appendChild(probe);
        const rect = svg.getBoundingClientRect();
        const width = Math.max(1, Math.ceil(rect.width));
        const height = Math.max(1, Math.ceil(rect.height));

        // 固定像素尺寸与颜色，便于后续绘制
        svg.setAttribute('width', String(width));
        svg.setAttribute('height', String(height));
        svg.style.color = color; // MathJax 字形使用 currentColor
        const svgString = new XMLSerializer().serializeToString(svg);
        document.body.removeChild(probe);

        const url = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svgString)}`;
        return await new Promise((resolve) => {
            const img = new Image();
            let settled = false;
            const finish = (value) => { if (!settled) { settled = true; resolve(value); } };
            const timer = setTimeout(() => finish(null), 5000);
            img.onload = () => { clearTimeout(timer); finish({ element: img, width, height }); };
            img.onerror = () => { clearTimeout(timer); finish(null); };
            try {
                img.src = url;
            } catch {
                clearTimeout(timer);
                finish(null);
            }
        });
    }

    // ==================== Canvas 工具 ====================

    _setFont(ctx, { size, weight = '400', mono = false }) {
        const family = mono ? this.monoFamily : this.fontFamily;
        ctx.font = `${weight} ${size}px ${family}`;
    }

    _wrapText(ctx, text, maxWidth) {
        const lines = [];
        const paragraphs = String(text == null ? '' : text).split('\n');

        for (const para of paragraphs) {
            if (para === '') { lines.push(''); continue; }

            let line = '';
            for (let i = 0; i < para.length; i++) {
                const ch = para[i];
                const test = line + ch;
                if (ctx.measureText(test).width > maxWidth && line !== '') {
                    const lastSpace = line.lastIndexOf(' ');
                    if (lastSpace > 0 && /[A-Za-z0-9]/.test(ch)) {
                        lines.push(line.slice(0, lastSpace));
                        line = line.slice(lastSpace + 1) + ch;
                    } else {
                        lines.push(line);
                        line = ch;
                    }
                } else {
                    line = test;
                }
            }
            if (line !== '') lines.push(line);
        }

        return lines.length ? lines : [''];
    }

    _clipToWidth(ctx, text, maxWidth) {
        if (ctx.measureText(text).width <= maxWidth) return text;
        const ellipsis = '…';
        let result = text;
        while (result.length > 1 && ctx.measureText(result + ellipsis).width > maxWidth) {
            result = result.slice(0, -1);
        }
        return result + ellipsis;
    }

    _roundRect(ctx, x, y, width, height, radius) {
        const r = Math.min(radius, width / 2, height / 2);
        ctx.beginPath();
        ctx.moveTo(x + r, y);
        ctx.arcTo(x + width, y, x + width, y + height, r);
        ctx.arcTo(x + width, y + height, x, y + height, r);
        ctx.arcTo(x, y + height, x, y, r);
        ctx.arcTo(x, y, x + width, y, r);
        ctx.closePath();
    }

    _canvasToBlob(canvas) {
        return new Promise((resolve, reject) => {
            try {
                canvas.toBlob((blob) => {
                    if (blob) resolve(blob);
                    else reject(new Error('canvas.toBlob returned null'));
                }, 'image/png');
            } catch (error) {
                reject(error);
            }
        });
    }
}

